/*
 * A098160  Numbers n with property that when writing down all the natural
 *          numbers from 0 to n one uses the same number of even and odd
 *          digits.
 * https://oeis.org/A098160
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn, fini, full
 * Formula:   Search natural numbers one by one, maintaining the running
 *            counts of even and odd decimal digits used from 0 up to the
 *            current number. Record the current number whenever the two
 *            counts are equal. The sequence is therefore generated by an
 *            exhaustive search
 * Range:     u8 n <= 18, u16 n <= 18, u32 n <= 18, u64 n <= 18, u128 n <= 18,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* seq_t and idx_t are provided by the build environment */
seq_t a(idx_t n)
{
    /* static state: list of found terms, current number, digit counts */
    static seq_t *terms = NULL;      /* array of sequence values */
    static size_t terms_len   = 0;   /* number of terms stored */
    static size_t terms_cap   = 0;   /* allocated capacity of terms */

    static idx_t current = 0;        /* last number examined */
    static idx_t even_cnt = 1;       /* digit '0' from number 0 */
    static idx_t odd_cnt  = 0;       /* digits seen so far in 0..current */

    /* initialise on first call */
    if (terms == NULL) {
        terms_cap = 16;                 /* initial capacity */
        terms     = (seq_t *)malloc(terms_cap * sizeof(seq_t));
        terms_len = 0;
    }

    /* expand the list until we have at least n terms */
    while (terms_len < (size_t)n) {
        /* move to the next natural number */
        current++;

        /* count digits of the new number */
        idx_t x = current;
        while (x > 0) {
            int d = x % 10;
            if ((d & 1) == 0)
                even_cnt++;
            else
                odd_cnt++;
            x /= 10;
        }

        /* if the two counts match, record this number */
        if (even_cnt == odd_cnt) {
            /* ensure capacity */
            if (terms_len == terms_cap) {
                terms_cap <<= 1;  /* double the capacity */
                terms = (seq_t *)realloc(terms, terms_cap * sizeof(seq_t));
            }
            terms[terms_len++] = (seq_t)current;
        }
    }

    /* return the nth term (1‑based indexing) */
    return terms[n - 1];
}
